// === ESTRUCTURA DEL PATRÓN CHAIN OF RESPONSIBILITY ===

// 1. Interfaz Handler (el contrato)
interface Handler {
  setNext(handler: Handler): Handler;
  handle(request: string): string | null;
}

// 2. Manejador Abstracto (implementación base)
abstract class AbstractHandler implements Handler {
  private nextHandler: Handler | null = null;

  setNext(handler: Handler): Handler {
    this.nextHandler = handler;
    return handler;
  }

  handle(request: string): string | null {
    if (this.nextHandler) {
      return this.nextHandler.handle(request);
    }
    return null;
  }
}

// 3. Manejadores Concretas
class AuthHandler extends AbstractHandler {
  handle(request: string): string | null {
    if (request === 'auth') {
      return 'Autenticación verificada';
    }
    return super.handle(request);
  }
}

class ValidationHandler extends AbstractHandler {
  handle(request: string): string | null {
    if (request === 'validate') {
      return 'Datos validados';
    }
    return super.handle(request);
  }
}

// 4. Cliente compone la cadena
const auth = new AuthHandler();
const validation = new ValidationHandler();
auth.setNext(validation);

auth.handle('validate'); // → 'Datos validados'
auth.handle('unknown');  // → null

