// 1. Interfaz común
interface TicketHandler {
  setNext(handler: TicketHandler): TicketHandler;
  handle(ticket: SupportTicket): string | null;
}

// 2. Manejadores concretos aislados
class PasswordHandler extends AbstractHandler {
  handle(ticket: SupportTicket): string | null {
    if (ticket.type === 'password') return 'Contraseña reseteada';
    return super.handle(ticket);
  }
}

class BillingHandler extends AbstractHandler {
  handle(ticket: SupportTicket): string | null {
    if (ticket.type === 'billing') return 'Factura corregida';
    return super.handle(ticket);
  }
}

// 3. Cliente compone la cadena
const password = new PasswordHandler();
const billing = new BillingHandler();
password.setNext(billing);

password.handle({ type: 'billing', message: '...' }); // → 'Factura corregida'

